#include <cstdio>
#include <vector>
#include <algorithm>
using namespace std;

const long long MOD = 998244353LL;

long long calc(int x, int y) {
    if (x <= 0 || y <= 0) return 0;
    if (x > y) swap(x, y);

    vector<long long> dp(x + 1), next(x + 1);
    for (int i = 1; i <= x; ++i) dp[i] = i + 1;

    for (int j = 2; j <= y; ++j) {
        next[1] = j + 1;
        for (int i = 2; i <= x; ++i) {
            next[i] = (dp[i - 1] * i + dp[i]) % MOD;
        }
        dp.swap(next);
    }
    return dp[x];
}

int main() {
    int a, b, c;
    if (scanf("%d%d%d", &a, &b, &c) != 3) return 0;

    long long answer = calc(a, b);
    answer = answer * calc(b, c) % MOD;
    answer = answer * calc(a, c) % MOD;

    printf("%lld\n", answer);
    return 0;
}

#include <cstdio>
#include <algorithm>
using namespace std;

const long long MOD = 998244353;

long long modPow(long long base, long long exp) {
    long long result = 1;
    while (exp) {
        if (exp & 1) result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return result;
}

int main() {
    int a, b, c;
    scanf("%d%d%d", &a, &b, &c);

    int n = max(a, max(b, c));
    long long* fact = new long long[n + 1];
    long long* invFact = new long long[n + 1];

    fact[0] = 1;
    for (int i = 1; i <= n; ++i)
        fact[i] = fact[i - 1] * i % MOD;

    invFact[n] = modPow(fact[n], MOD - 2);
    for (int i = n; i > 0; --i)
        invFact[i - 1] = invFact[i] * i % MOD;

    auto calc = [&](int x, int y) {
        long long result = 0;
        for (int i = 0; i <= min(x, y); ++i) {
            long long term = fact[x] * fact[y] % MOD;
            term = term * invFact[x - i] % MOD;
            term = term * invFact[y - i] % MOD;
            term = term * invFact[i] % MOD;
            result = (result + term) % MOD;
        }
        return result;
    };

    long long answer = calc(a, b) * calc(b, c) % MOD * calc(a, c) % MOD;
    printf("%lld\n", answer);

    delete[] fact;
    delete[] invFact;
    return 0;
}

